/**
 * Medicare Part D GLP-1 diabetes spending (2026).
 *
 * Core question: How much of Part D drug spending now sits in GLP-1
 * diabetes indications, and which plan sponsors carry that utilization risk?
 *
 * Perimeter: CMS Part D Spending by Drug / PDE-derived class totals via KFF
 * and MedPAC Data Book; CMS Part D Prescribers brand costs for the four
 * largest diabetes-labeled GLP-1 brands; KFF Part D enrollment by parent
 * organization for plan-side concentration. Gross (point-of-sale) dollars
 * unless labeled net-of-rebate estimates.
 *
 * Headline: Gross Part D GLP-1 spend hit ~$27.5B in 2024 (~5?? 2019); four
 * diabetes brands alone were ~$24.6B / ~11% of one CMS program total; top-5
 * sponsors enroll 73.5% of Part D members who absorb that class risk.
 */

export type Confidence = "disclosed" | "estimated" | "carried";

export const SOURCE_NOTE =
  "GLP-1 class gross spend and beneficiary counts: KFF analysis of CMS Part D claims, 2019???2024 (Jan 2026 brief). Brand-level 2024 costs/claims: CMS Medicare Part D Prescribers by Provider and Drug (data year 2024; aggregated public analyses). Therapeutic-class context and rebate bands: MedPAC July 2026 Data Book, Charts 10-21 / 10-25 (Part D PDE + DIR). Plan-sponsor enrollment: KFF Key Facts on Part D Enrollment 2025 (CMS enrollment files). Gross spending excludes confidential manufacturer rebates; MedPAC places diabetic-therapy rebates at ???50% of gross in 2023???2024. Enrollment shares are not drug-specific spend shares ??? they locate which sponsors??? books carry the utilization.";

export const SOURCES = [
  {
    label: "KFF ??? Recent Trends in GLP-1 Use and Spending in Medicare (Jan 2026)",
