    label: "KFF ??? Key Facts About Medicare Part D Enrollment 2025",
    url: "https://www.kff.org/medicare/key-facts-about-medicare-part-d-enrollment-premiums-and-cost-sharing-in-2025/",
  },
  {
    label: "MedPAC ??? Part D status report (Jan 2026 briefing)",
    url: "https://www.medpac.gov/wp-content/uploads/2025/08/Tab-L-Part-D-status-report-Jan-2026.pdf",
