"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import {
  BRAND_SPEND_2024,
  CHANNEL_COMPARE,
  COST_INTENSITY,
  GROSS_VS_NET,
  HEADLINE,
  SOURCE_NOTE,
  SPONSOR_ENROLLMENT_2025,
  THERAPEUTIC_CLASSES_2024,
  YEAR_TREND,
  filterSponsorsByChannel,
  type PlanChannel,
} from "@/data/medicare-part-d-glp-1-diabetes-spending-2026-data";

type Panel =
  | "spend-path"
  | "brand-stack"
  | "class-ladder"
  | "sponsor-map"
  | "gross-net";

type Metric = "spend" | "claims";

const COLORS = {
  primary: "#0e7490",
  secondary: "#b45309",
