/**
 * QA: medicare-part-d-glp-1-diabetes-spending-2026
 * // viz-types: composed area+line, horizontal bar, horizontal bar, pie+bar, bar | layout: default
 * // smoke-marker: Gross GLP-1 Part D spend
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";
import { startStaticServer, stopStaticServer } from "./lib/static-server.mjs";
import { auditVizInteractions } from "./lib/viz-interaction-qa.mjs";
import {
  BRAND_SPEND_2024,
  HEADLINE,
  SPONSOR_ENROLLMENT_2025,
  THERAPEUTIC_CLASSES_2024,
  YEAR_TREND,
} from "../src/data/medicare-part-d-glp-1-diabetes-spending-2026-data.ts";

assert.equal(HEADLINE.glp1GrossSpend2024B, 27.5);
assert.equal(HEADLINE.foldIncrease2019to2024, 5);
assert.equal(HEADLINE.fourBrandCore2024B, 24.57);
assert.equal(HEADLINE.fourBrandShareOfProgramPct, 10.8);
assert.equal(HEADLINE.top5SponsorEnrollmentSharePct, 73.5);
assert.equal(HEADLINE.ozempicEnrollees2024M, 2.0);
assert.ok(BRAND_SPEND_2024.length >= 4);
assert.ok(YEAR_TREND.length >= 6);
assert.ok(THERAPEUTIC_CLASSES_2024.length >= 4);
assert.ok(SPONSOR_ENROLLMENT_2025.length >= 4);
assert.equal(BRAND_SPEND_2024[0].brand, "Ozempic");

const root = process.cwd();
const slug = "medicare-part-d-glp-1-diabetes-spending-2026";
const markers = [
  "Gross GLP-1 Part D spend",
  "Health Economics ?? Part D pharmacy",
];

async function clickBtn(page, name) {
  console.log(`??? click ${name}`);
  await page.locator("button", { hasText: name }).first().click({ timeout: 8000 });
  await page.waitForTimeout(200);
}

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4184);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.setDefaultTimeout(15000);
  try {
    await page.goto(`http://127.0.0.1:${port}/blog/${slug}.html`, {
      waitUntil: "domcontentloaded",
      timeout: 45000,
    });
    await page.waitForSelector(`[data-viz="${slug}"]`, { timeout: 20000 });
    for (const m of markers) {
      await page.getByText(m, { exact: false }).first().waitFor({
        state: "attached",
        timeout: 20000,
      });
      console.log(`??? ${m}`);
    }
    await clickBtn(page, "Four diabetes");
    await clickBtn(page, "Where diabetic");
    await clickBtn(page, "Which plan");
    await page.locator("select").nth(0).selectOption("pdp");
    await page.waitForTimeout(200);
    await page.locator("select").nth(0).selectOption("ma-pd");
    await page.waitForTimeout(200);
    await page.locator("select").nth(1).selectOption("claims");
    await page.waitForTimeout(200);
    await clickBtn(page, "Gross headlines");
    await clickBtn(page, "Gross GLP-1");
    await page.locator("select").nth(0).selectOption("all");
    await page.locator("select").nth(1).selectOption("spend");
    const audit = await auditVizInteractions(page, { slug });
    console.log("audit", audit);
    console.log(`??? QA passed for ${slug}`);
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

