                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={95}
                    paddingAngle={2}
                    label={({ name, percent }) =>
                      `${String(name).split(" ")[0]} ${((percent ?? 0) * 100).toFixed(0)}%`
                    }
                  >
                    {pieData.map((entry, i) => (
                      <Cell
                        key={entry.name}
                        fill={
                          [
                            COLORS.primary,
                            COLORS.secondary,
                            COLORS.trulicity,
                            COLORS.accent,
                            COLORS.soft,
                          ][i % 5]
                        }
                      />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(value: number, _n, props) => [
                      `${value.toFixed(1)}M enrollees`,
                      (props.payload as { name: string }).name,
                    ]}
                  />
                </PieChart>
              </ResponsiveContainer>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={CHANNEL_COMPARE}
                  margin={{ top: 8, right: 8, left: 0, bottom: 0 }}
                >
                  <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                  <XAxis dataKey="channel" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip
                    formatter={(value: number, name: string) => {
                      if (name === "enrollees2025M")
                        return [`${value}M`, "Enrollees 2025"];
                      if (name === "grossSpendPmpm")
                        return [`$${value}`, "Gross PMPM (2024)"];
                      if (name === "glp1ExposureIndex")
                        return [value, "Enrollment-weighted exposure index"];
                      return [value, name];
                    }}
                  />
                  <Legend />
                  <Bar
                    dataKey="enrollees2025M"
                    name="Enrollees (M)"
                    fill={COLORS.primary}
                    radius={[4, 4, 0, 0]}
                  />
                  <Bar
                    dataKey="glp1ExposureIndex"
                    name="Exposure index"
                    fill={COLORS.secondary}
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}

          {panel === "gross-net" && (
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart
                data={GROSS_VS_NET}
                margin={{ top: 8, right: 12, left: 0, bottom: 40 }}
              >
                <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                <XAxis
                  dataKey="scenario"
                  tick={{ fontSize: 9 }}
                  interval={0}
                  angle={-18}
                  textAnchor="end"
                  height={60}
                />
                <YAxis
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `$${v}B`}
                />
                <Tooltip
                  formatter={(value: number) => [formatB(value), "Amount"]}
                  labelFormatter={(label) => String(label)}
                />
                <Bar
                  dataKey="amountB"
                  name="Amount ($B)"
                  fill={COLORS.primary}
                  radius={[4, 4, 0, 0]}
                >
                  {GROSS_VS_NET.map((row) => (
                    <Cell
                      key={row.scenario}
                      fill={
                        row.scenario.includes("Net")
                          ? COLORS.secondary
                          : row.scenario.includes("Injectable")
                            ? COLORS.soft
                            : COLORS.primary
                      }
                    />
                  ))}
                </Bar>
              </ComposedChart>
            </ResponsiveContainer>
          )}
        </div>

        {panel === "gross-net" && (
          <div className="mt-3 grid grid-cols-1 gap-2 sm:grid-cols-2">
            {COST_INTENSITY.map((row) => (
              <div
                key={row.label}
                className="rounded-lg border border-slate-100 bg-slate-50 px-3 py-2"
              >
                <p className="text-xs font-medium text-slate-700">{row.label}</p>
                <p className="text-sm text-slate-900">
                  ${row.costPerClaim.toLocaleString()} / claim ??{" "}
                  {row.claimsSharePct}% of claims ?? {row.spendSharePct}% of spend
                </p>
              </div>
            ))}
          </div>
        )}

        {panel === "sponsor-map" && (
          <p className="mt-2 text-xs text-slate-500">
            Channel filter rescales sponsor bars using disclosed PDP/MA-PD market
            tilts (Centene PDP-heavy; UnitedHealth MA-PD-heavy). Enrollment ???
            published GLP-1 dollar share.
            {channel !== "all"
              ? ` Showing ${channel === "pdp" ? "PDP" : "MA-PD"} tilt.`
              : ""}
          </p>
        )}
      </div>

      <div className="border-t border-slate-100 px-4 py-3 sm:px-6">
        <p className="text-[11px] leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
        <p className="mt-1 text-[11px] text-slate-400">
          Sponsors in view:{" "}
          {SPONSOR_ENROLLMENT_2025.map((s) => s.sponsor).join(" ?? ")}
        </p>
      </div>
    </div>
  );
}

