                          ? COLORS.secondary
                          : row.scenario.includes("Injectable")
                            ? COLORS.soft
                            : COLORS.primary
                      }
                    />
                  ))}
                </Bar>
              </ComposedChart>
            </ResponsiveContainer>
          )}
        </div>

        {panel === "gross-net" && (
          <div className="mt-3 grid grid-cols-1 gap-2 sm:grid-cols-2">
