                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={95}
                    paddingAngle={2}
                    label={({ name, percent }) =>
                      `${String(name).split(" ")[0]} ${((percent ?? 0) * 100).toFixed(0)}%`
                    }
                  >
                    {pieData.map((entry, i) => (
                      <Cell
                        key={entry.name}
                        fill={
                          [
                            COLORS.primary,
                            COLORS.secondary,
                            COLORS.trulicity,
                            COLORS.accent,
                            COLORS.soft,
                          ][i % 5]
                        }
                      />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(value: number, _n, props) => [
                      `${value.toFixed(1)}M enrollees`,
                      (props.payload as { name: string }).name,
