"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import {
  BRAND_SPEND_2024,
  CHANNEL_COMPARE,
  COST_INTENSITY,
  GROSS_VS_NET,
  HEADLINE,
  SOURCE_NOTE,
  SPONSOR_ENROLLMENT_2025,
  THERAPEUTIC_CLASSES_2024,
  YEAR_TREND,
  filterSponsorsByChannel,
  type PlanChannel,
} from "@/data/medicare-part-d-glp-1-diabetes-spending-2026-data";

type Panel =
  | "spend-path"
  | "brand-stack"
  | "class-ladder"
  | "sponsor-map"
  | "gross-net";

type Metric = "spend" | "claims";

const COLORS = {
  primary: "#0e7490",
  secondary: "#b45309",
  accent: "#be123c",
  soft: "#64748b",
  grid: "#e2e8f0",
  ozempic: "#0e7490",
  mounjaro: "#c2410c",
  trulicity: "#7c3aed",
  rybelsus: "#059669",
  other: "#94a3b8",
};

const BRAND_COLOR: Record<string, string> = {
  ozempic: COLORS.ozempic,
  mounjaro: COLORS.mounjaro,
  trulicity: COLORS.trulicity,
  rybelsus: COLORS.rybelsus,
  other: COLORS.other,
};

const PANEL_META: Record<Panel, { title: string; subtitle: string }> = {
  "spend-path": {
    title: "Gross GLP-1 Part D spend & claims path",
    subtitle:
      "KFF/CMS endpoints 2019 & 2024; mid years interpolated for shape only",
  },
  "brand-stack": {
    title: "Four diabetes brands dominate the class",
    subtitle:
      "CMS Part D Prescribers 2024 ??? Ozempic alone ~$12.4B gross",
  },
  "class-ladder": {
    title: "Where diabetic injectables sit in Part D",
    subtitle:
      "MedPAC Chart 10-25 ??? injectable antidiabetics = 12.1% of gross Part D",
  },
  "sponsor-map": {
    title: "Which plan sponsors carry the enrollment risk",
    subtitle:
      "KFF 2025 ??? top five firms enroll 73.5% of Part D members",
  },
  "gross-net": {
    title: "Gross headlines vs rebate-adjusted scale",
    subtitle:
      "KFF 50% rebate illustration + MedPAC diabetic rebate band ???50%",
  },
};

const PANELS: Panel[] = [
  "spend-path",
  "brand-stack",
  "class-ladder",
  "sponsor-map",
  "gross-net",
];

function formatB(n: number): string {
  return `$${n.toFixed(n >= 10 ? 1 : 2)}B`;
}

function tipNum(value: unknown): number {
  return typeof value === "number" ? value : Number(value ?? 0);
}

export function MedicarePartDGlp1DiabetesSpending2026Dashboard() {
  const [panel, setPanel] = useState<Panel>("spend-path");
  const [channel, setChannel] = useState<PlanChannel>("all");
  const [metric, setMetric] = useState<Metric>("spend");

  const sponsors = useMemo(
    () => filterSponsorsByChannel(channel),
    [channel],
  );

  const trendChart = useMemo(
    () =>
      YEAR_TREND.map((r) => ({
        year: r.year,
        spendB: r.grossSpendB,
        claimsM: r.claimsM,
        ozempicK: r.ozempicEnrolleesK,
        mounjaroK: r.mounjaroEnrolleesK ?? 0,
      })),
    [],
  );

  const brandChart = useMemo(
    () =>
      BRAND_SPEND_2024.map((r) => ({
        name: r.brand,
        id: r.id,
        spendB: r.spendB,
        claimsM: r.claimsM,
        costPerClaim: r.costPerClaim,
      })),
    [],
  );

  const classChart = useMemo(
    () =>
      [...THERAPEUTIC_CLASSES_2024]
        .sort((a, b) => a.spendB - b.spendB)
        .map((r) => ({
          name: r.className.replace("Antidiabetic ??? ", "DM ?? "),
          spendB: r.spendB,
          sharePct: r.sharePct,
          rebateBand: r.rebateBand,
        })),
    [],
  );

  const pieData = useMemo(
    () =>
      sponsors.map((s) => ({
        name: s.sponsor,
        value: s.enrolleesM,
        sharePct: s.sharePct,
      })),
    [sponsors],
  );

  const meta = PANEL_META[panel];

  return (
    <div className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-200 bg-gradient-to-r from-slate-900 via-cyan-950 to-slate-900 px-4 py-4 sm:px-6">
        <p className="text-xs font-medium uppercase tracking-wider text-cyan-300/90">
          Health Economics ?? Part D pharmacy
        </p>
        <h3 className="mt-1 text-lg font-semibold text-white sm:text-xl">
          GLP-1 diabetes drugs now take ~1 in 10 Part D dollars
        </h3>
        <p className="mt-1 max-w-3xl text-sm text-slate-300">
          Gross class spend ~{formatB(HEADLINE.glp1GrossSpend2024B)} in 2024 (
          {HEADLINE.foldIncrease2019to2024}?? since 2019). Four diabetes brands
          alone were {formatB(HEADLINE.fourBrandCore2024B)} (
          {HEADLINE.fourBrandShareOfProgramPct}% of one CMS program total). Top-5
          sponsors enroll {HEADLINE.top5SponsorEnrollmentSharePct}% of Part D
          members who absorb that utilization risk.
        </p>
        <div className="mt-3 flex flex-wrap gap-2 text-xs text-slate-200">
          <span className="rounded-md bg-white/10 px-2 py-1">
            Ozempic enrollees: {HEADLINE.ozempicEnrollees2024M}M
          </span>
          <span className="rounded-md bg-white/10 px-2 py-1">
            Claims: {HEADLINE.glp1Claims2019M}M ??? {HEADLINE.glp1Claims2024M}M
          </span>
          <span className="rounded-md bg-white/10 px-2 py-1">
            Net @50% rebate ??? {formatB(HEADLINE.glp1NetSpendEst2024B)}
          </span>
        </div>
      </div>

      <div className="flex flex-col gap-3 border-b border-slate-100 bg-slate-50 px-4 py-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between sm:px-6">
        <div className="flex flex-wrap gap-1.5">
          {PANELS.map((id) => (
            <button
              key={id}
              type="button"
              onClick={() => setPanel(id)}
              className={`rounded-md px-2.5 py-1.5 text-xs font-medium transition ${
                panel === id
                  ? "bg-cyan-800 text-white"
                  : "bg-white text-slate-600 ring-1 ring-slate-200 hover:bg-slate-100"
              }`}
            >
              {PANEL_META[id].title.split(" ").slice(0, 3).join(" ")}
            </button>
          ))}
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <label className="flex items-center gap-1.5 text-xs text-slate-600">
            Channel
            <select
              value={channel}
              onChange={(e) => setChannel(e.target.value as PlanChannel)}
              className="rounded-md border border-slate-200 bg-white px-2 py-1 text-xs text-slate-800"
            >
              <option value="all">All Part D</option>
              <option value="pdp">PDP tilt</option>
              <option value="ma-pd">MA-PD tilt</option>
            </select>
          </label>
          <label className="flex items-center gap-1.5 text-xs text-slate-600">
            Metric
            <select
              value={metric}
              onChange={(e) => setMetric(e.target.value as Metric)}
              className="rounded-md border border-slate-200 bg-white px-2 py-1 text-xs text-slate-800"
            >
              <option value="spend">Gross spend</option>
              <option value="claims">Claims volume</option>
            </select>
          </label>
        </div>
      </div>

      <div className="px-4 py-4 sm:px-6">
        <div className="mb-3">
          <h4 className="text-sm font-semibold text-slate-900">{meta.title}</h4>
          <p className="text-xs text-slate-500">{meta.subtitle}</p>
        </div>

        <div className="h-[340px] w-full sm:h-[380px]">
          {panel === "spend-path" && (
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={trendChart} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                <YAxis
                  yAxisId="left"
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => (metric === "spend" ? `$${v}B` : `${v}M`)}
                />
                <YAxis
                  yAxisId="right"
                  orientation="right"
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `${v / 1000}M`}
                />
                <Tooltip
                  formatter={(value, name) => {
                    const v = tipNum(value);
                    const n = String(name);
                    if (n === "spendB") return [formatB(v), "Gross spend"];
                    if (n === "claimsM") return [`${v}M`, "Claims"];
                    if (n === "ozempicK") return [`${v}k`, "Ozempic enrollees"];
                    if (n === "mounjaroK") return [`${v}k`, "Mounjaro enrollees"];
                    return [v, n];
                  }}
                />
                <Legend />
                {metric === "spend" ? (
                  <Area
                    yAxisId="left"
                    type="monotone"
                    dataKey="spendB"
                    name="Gross spend ($B)"
                    fill={COLORS.primary}
                    fillOpacity={0.25}
                    stroke={COLORS.primary}
                    strokeWidth={2}
                  />
                ) : (
                  <Bar
                    yAxisId="left"
                    dataKey="claimsM"
                    name="Claims (M)"
                    fill={COLORS.primary}
                    radius={[4, 4, 0, 0]}
                  />
                )}
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="ozempicK"
                  name="Ozempic enrollees (k)"
                  stroke={COLORS.accent}
                  strokeWidth={2}
                  dot={{ r: 3 }}
                />
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="mounjaroK"
                  name="Mounjaro enrollees (k)"
                  stroke={COLORS.secondary}
                  strokeWidth={2}
                  strokeDasharray="4 3"
                  dot={{ r: 3 }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          )}

          {panel === "brand-stack" && (
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={brandChart}
                layout="vertical"
                margin={{ top: 8, right: 16, left: 8, bottom: 0 }}
              >
                <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                <XAxis
                  type="number"
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) =>
                    metric === "spend" ? `$${v}B` : `${v}M`
                  }
                />
                <YAxis
                  type="category"
                  dataKey="name"
                  width={88}
                  tick={{ fontSize: 11 }}
                />
                <Tooltip
                  formatter={(value, name) => {
                    const v = tipNum(value);
                    const n = String(name);
                    if (n === "spendB") return [formatB(v), "Gross spend"];
                    if (n === "claimsM") return [`${v.toFixed(2)}M`, "Claims"];
                    if (n === "costPerClaim")
                      return [`$${v.toLocaleString()}`, "Cost / claim"];
                    return [v, n];
                  }}
                />
                <Bar
                  dataKey={metric === "spend" ? "spendB" : "claimsM"}
                  name={metric === "spend" ? "Gross spend ($B)" : "Claims (M)"}
                  radius={[0, 4, 4, 0]}
                >
                  {brandChart.map((row) => (
                    <Cell key={row.id} fill={BRAND_COLOR[row.id] ?? COLORS.soft} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          )}

          {panel === "class-ladder" && (
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={classChart}
                layout="vertical"
                margin={{ top: 8, right: 16, left: 4, bottom: 0 }}
              >
                <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                <XAxis
                  type="number"
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `$${v}B`}
                />
                <YAxis
                  type="category"
                  dataKey="name"
                  width={130}
                  tick={{ fontSize: 10 }}
                />
                <Tooltip
                  formatter={(value, name, item) => {
                    const v = tipNum(value);
                    const n = String(name);
                    if (n === "spendB") {
                      const share = (
                        item?.payload as { sharePct?: number } | undefined
                      )?.sharePct;
                      return [
                        `${formatB(v)}${share != null ? ` (${share}% of Part D)` : ""}`,
                        "Gross spend",
                      ];
                    }
                    return [v, n];
                  }}
                  labelFormatter={(label) => String(label)}
                />
                <Bar dataKey="spendB" name="Gross spend ($B)" radius={[0, 4, 4, 0]}>
                  {classChart.map((row) => (
                    <Cell
                      key={row.name}
                      fill={
                        row.name.includes("injectable") || row.name.includes("DM ?? injectable")
                          ? COLORS.accent
                          : row.name.includes("oral") || row.name.includes("DM ?? oral")
                            ? COLORS.secondary
                            : COLORS.primary
                      }
                    />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          )}

          {panel === "sponsor-map" && (
            <div className="grid h-full grid-cols-1 gap-3 sm:grid-cols-2">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={pieData}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={95}
                    paddingAngle={2}
                    label={({ name, percent }) =>
                      `${String(name).split(" ")[0]} ${((percent ?? 0) * 100).toFixed(0)}%`
                    }
                  >
                    {pieData.map((entry, i) => (
                      <Cell
                        key={entry.name}
                        fill={
                          [
                            COLORS.primary,
                            COLORS.secondary,
                            COLORS.trulicity,
                            COLORS.accent,
                            COLORS.soft,
                          ][i % 5]
                        }
                      />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(value, _n, item) => [
                      `${tipNum(value).toFixed(1)}M enrollees`,
                      (item?.payload as { name?: string } | undefined)?.name ??
                        "Sponsor",
                    ]}
                  />
                </PieChart>
              </ResponsiveContainer>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={CHANNEL_COMPARE}
                  margin={{ top: 8, right: 8, left: 0, bottom: 0 }}
                >
                  <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                  <XAxis dataKey="channel" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip
                    formatter={(value, name) => {
                      const v = tipNum(value);
                      const n = String(name);
                      if (n === "enrollees2025M")
                        return [`${v}M`, "Enrollees 2025"];
                      if (n === "grossSpendPmpm")
                        return [`$${v}`, "Gross PMPM (2024)"];
                      if (n === "glp1ExposureIndex")
                        return [v, "Enrollment-weighted exposure index"];
                      return [v, n];
                    }}
                  />
                  <Legend />
                  <Bar
                    dataKey="enrollees2025M"
                    name="Enrollees (M)"
                    fill={COLORS.primary}
                    radius={[4, 4, 0, 0]}
                  />
                  <Bar
                    dataKey="glp1ExposureIndex"
                    name="Exposure index"
                    fill={COLORS.secondary}
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}

          {panel === "gross-net" && (
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart
                data={GROSS_VS_NET}
                margin={{ top: 8, right: 12, left: 0, bottom: 40 }}
              >
                <CartesianGrid stroke={COLORS.grid} strokeDasharray="3 3" />
                <XAxis
                  dataKey="scenario"
                  tick={{ fontSize: 9 }}
                  interval={0}
                  angle={-18}
                  textAnchor="end"
                  height={60}
                />
                <YAxis
                  tick={{ fontSize: 11 }}
